iterations.implement_summary:
{
  "wiring": {
    "supply_volts": "24 VDC (C2) from the CF-IO8 sensor supply rail, which is 24 VDC -5%/+5% at the PCB terminals (22.8 V to 25.2 V, C3)",
    "wire_gauge_and_run": "22 AWG solid copper (C7), 3 ft one-way run between CF-IO8 terminals and sensor head terminals, installed as one 3-conductor cable. No intermediate junction block.",
    "voltage_drop": "V_drop = 2 \u00d7 3 ft \u00d7 0.01614 ohm/ft \u00d7 0.050 A = 0.0048 V (4.84 mV) (C10). Expected powered voltage at sensor head under load: 22.795 V to 25.205 V.",
    "output_type_and_matching": "The Keyence LV-N11N has an NPN open-collector output (C11), 30 V max rating, sinking. The CF-IO8 DI0-DI7 inputs are designed for NPN open-collector sensor outputs: the sensor pulls the input to 0 V to register ON. Therefore, the LV-N11N output connects directly to DI3 with no pull-up resistor, no series resistor, no signal conditioner, and no logic inversion. A PNP (sourcing) sensor would not be a direct match for DI3 and is out of scope.",
    "termination": "Connect 24 V to sensor +V terminal, 0 V to sensor 0 V terminal, and output to CF-IO8 DI3 (registration-mark input, C11). Conductor color coding follows device terminal markings and CF-IO8 wiring drawing at install.",
    "mechanical": "Strain-relief clamp within 150 mm of the sensor and within 150 mm of the CF-IO8 terminal block. Minimum bend radius 5 \u00d7 cable outer diameter. Route at least 100 mm from motor/VFD power cabling or cross at 90 degrees. Terminate with torque per CF-IO8 drawing. Solid conductor must not be flexed after termination."
  },
  "parts": {
    "bill_of_materials": [
      {
        "qty": 1,
        "part_number": "Keyence LV-N11N",
        "description": "registration-mark laser sensor",
        "supply": "24 VDC (C2)",
        "output": "NPN open-collector (C11)",
        "current_consumption": "50 mA (C5)",
        "unit_cost": "$214.00 USD (C15)"
      },
      {
        "qty": 1,
        "part_number": "22 AWG solid copper conductor",
        "description": "3 ft (C7)",
        "supply": "N/A",
        "output": "N/A",
        "current_consumption": "N/A",
        "unit_cost": "$0.00 incremental (shop stock)"
      }
    ],
    "bom_total": "$214.00 USD (C15)",
    "notes": "The Keyence LV-N11N is the only approved registration-mark sensor for Line 4; no substitute part number is permitted. The unverified marketing figure of 36,200 found in research material has no verified currency and is superseded by the approved-parts figure of $214.00 (C15). If the delivered unit requires a separate optical head not on the Line 4 approved-parts list, procurement stops (K4)."
  },
  "commissioning": {
    "preconditions": "Machine stopped and locked out per IEC 60204-1 (C16) and site procedure before landing conductors. Wiring inspected per 2.5. CF-IO8 DI3 confirmed as the registration-mark input (C11). Machine set to 150 cups per minute (C12). Instruments: DMM with DC volts (0.5% or better) and CF-IO8 DI3 counter (or external pulse counter/logger on DI3).",
    "check_1": {
      "name": "Powered voltage at sensor head",
      "procedure": "With machine powered and sensor switching, probe +24 V and 0 V at the SENSOR HEAD terminals (not at PCB). Log min and max over 60 seconds.",
      "pass_band": "PASS if 21.6 V \u2264 V_head \u2264 26.4 V (C4). Record minimum value \u2014 it is the falsifier input (Step 5)."
    },
    "check_2": {
      "name": "Output switching at maximum line speed",
      "procedure": "Reset DI3 counter at T0. Run machine at 150 cups per minute (C12) for exactly 60 seconds. Stop. Read counter.",
      "pass_band": "PASS if counter reads exactly 150 of 150 (C14) with zero missed marks. Expected mark spacing: 400 ms (C13)."
    },
    "response_mode": "The LV-N11N offers response modes: 80 us (HIGH SPEED), 250 us (FINE), 500 us (TURBO), 1 ms (SUPER), 4 ms (ULTRA), 16 ms (MEGA). Start at 250 us (FINE). If Check 2 reports missed marks, switch to 80 us (HIGH SPEED) and re-run once. If Check 2 reports spurious extra counts (paper dust / ambient light), step coarser to 500 us (TURBO) and re-run once. The accepted mode is recorded on the commissioning sheet. Any further failure is a fail-closed stop (K3). Even the slowest mode (16 ms) is 4% of the 400 ms mark period (C13), so the amplifier re-arms between marks in every mode.",
    "fail_closed_rule": "A short count is never resolved by re-running the test. Stop, record the count and active mode, and re-derive the required response time from mark width and web speed (K3) before any further attempt.",
    "records": "Commissioning sheet must include: part number (C1), voltage drop figure (C10), wire gauge and length (C7), output type (C11), results of Check 1 and Check 2 with their 60-second windows, and the accepted response mode."
  },
  "falsifier": {
    "metric": "Minimum sensor-head supply voltage sampled during the 60-second maximum-speed run of Check 2",
    "threshold": "Below 21.6 V at any sample",
    "window": "60 s run at 150 cups per minute",
    "meaning": "If the threshold is breached, the conductor sizing claim (22 AWG, 3 ft, 50 mA basis \u2014 C7/C5/C10) is refuted. Stop. Measure actual loop current and conductor resistance. Re-derive voltage drop per Step 1.3. Re-approve the design. Do not re-terminate or re-run without re-derivation.",
    "note": "The 150/150 count of Check 2 qualifies the optical setup and input matching; the voltage floor is what qualifies the conductor sizing."
  },
  "kill_triggers": [
    {
      "id": "K1",
      "condition": "If the installed conductor is not 22 AWG solid copper (e.g., different gauge, stranded, tinned, or copper-clad aluminium)",
      "action": "Stop before energizing. Re-run Step 1.3 using the conductor datasheet resistance value."
    },
    {
      "id": "K2",
      "condition": "If an ammeter in the 0 V return conductor reads above 100 mA during Check 2",
      "action": "Stop. Re-derive voltage drop using the measured current; that exceeds the sensor output rating."
    },
    {
      "id": "K3",
      "condition": "If Check 2 reads fewer than 150 marks in 60 s even in the fastest mode (80 us)",
      "action": "Stop. Obtain registration mark width and web speed. Re-derive required response time. Re-approve. Do not accept installation or re-run test as workaround."
    },
    {
      "id": "K4",
      "condition": "If the delivered LV-N11N unit requires a separate optical head not on the Line 4 approved-parts list",
      "action": "Stop procurement and installation. Have the head approved and re-estimated before continuing \u2014 the $214.00 total (C15) would be incomplete."
    },
    {
      "id": "K5",
      "condition": "If device terminal markings or CF-IO8 wiring drawing disagree with landed wiring",
      "action": "Power down. Re-map from physical markings. Never infer from color alone."
    },
    {
      "id": "K6",
      "condition": "If any part of the 3 ft run sits on a moving structure or must flex in service",
      "action": "Stop. Substitute stranded conductor. Re-run Step 1.3 before energizing."
    },
    {
      "id": "K7",
      "condition": "If procurement confirms a different currency basis for the $214.00 cost",
      "action": "Correct C15 in all three sections simultaneously. Never carry two cost figures."
    }
  ],
  "risks_and_mitigations": [
    {
      "risk": "Paper dust on optics",
      "mitigation": "Scheduled cleaning and air purge if available. Watch for counts above 150 in production."
    },
    {
      "risk": "Ambient light interference",
      "mitigation": "Aim laser spot away from cup-former lamp/strobe. Confirm no over-count in Check 2."
    },
    {
      "risk": "Vibration",
      "mitigation": "Strain relief within 150 mm at both ends, bend radius 5 \u00d7 OD, no flexing after termination (K6)."
    },
    {
      "risk": "EMI",
      "mitigation": "Keep 3 ft run at least 100 mm from motor/VFD power cabling or cross at 90 degrees (2.6)."
    },
    {
      "risk": "Terminal loosening",
      "mitigation": "Torque per CF-IO8 drawing. Re-checked at first scheduled maintenance after commissioning."
    }
  ],
  "governing_code": "IEC 60204-1 (C16)"
}

